python3 - <<'EOF'
import re
text = open('input.tex').read()
words = text.split()
for i, line in enumerate(open('synonyms.txt'), 1):
    fam = [w.strip() for w in line.strip().split(',') if w.strip()]
    for w in fam:
        for j, tw in enumerate(words, 1):
            clean = re.sub(r'[^a-zA-Z-]', '', tw)
            if clean.lower() == w.lower():
                print(f"line {i:3d} fam[{w:18s}]  input word #{j:3d}: {tw}")
EOF

perl - <<'EOF'
open(T, '<', 'input.tex') or die;
@words = <T>;
close T;
@words = split /\s+/, join('', @words);
open(S, '<', 'synonyms.txt') or die;
while (<S>) {
    chomp;
    my @fam = map { s/^\s+|\s+$//g; $_ } split /,/, $_;
    for my $w (@fam) {
        my $i = 0;
        for my $tw (@words) {
            $i++;
            (my $c = $tw) =~ s/[^a-zA-Z-]//g;
            print "fam[$w]  word#$i: $tw\n" if lc($c) eq lc($w);
        }
    }
}
EOF

mkdir -p /tmp/probe && cat > /tmp/probe/p5.tex <<'EOF'
\documentclass[letterpaper]{article}
\setlength{\topmargin}{2in}
\setlength{\headheight}{0pt}
\setlength{\headsep}{0pt}
\setlength{\textheight}{5in}
\setlength{\textwidth}{2.5in}
\setlength{\oddsidemargin}{2in}
\setlength{\evensidemargin}{2in}
\setlength{\footskip}{0.5in}
\tracingonline=1
\begin{document}
\showoutput
He didn't say any more, but we've always been unusually communicative in a reserved way, and I understood that he meant a great deal more than that. In consequence, I'm inclined to reserve all judgments, a habit that has opened up many odd natures to me and also made me the victim of not a few veteran bores. The abnormal mind is quick to detect and attach itself to this quality when it appears in a normal person, and so it came about that in college I was unjustly accused of being a politician, because I was privy to the secret griefs of wild, unknown men. Most of the confidences were unsought---frequently I have feigned sleep, preoccupation, or a hostile levity when I realized by some unmistakable sign that an intimate revelation was quivering on the horizon; for the intimate revelations of young men, or at least the terms in which they express them, are usually plagiaristic and marred by obvious suppressions. Reserving judgments is a matter of infinite hope. I am still a little afraid of missing something if I forget that, as my father snobbishly suggested, and I snobbishly repeat, a sense of the fundamental decencies is parcelled out unequally at birth.
\end{document}
EOF
pdflatex -interaction=nonstopmode -output-directory=/tmp/probe /tmp/probe/p5.tex >/dev/null 2>&1; grep -A1 "^^A" /tmp/probe/p5.log | head -5; grep "line 1" /tmp/probe/p5.log | head -40

perl - <<'EOF'
open(L,'<','/tmp/probe/p5.log') or die;
@lines = <L>; close L;
my @out; my $in=0; my $cur;
for my $l (@lines) {
  if ($l =~ /^\.+\\hbox\([\d.]+\+[\d.]+\)\s*(?:x([\d.]+))?,? glue set /) {
    push @out, $cur if defined $cur;
    $cur = "";
  } elsif (defined $cur && $l =~ /^\.+\\OT1\/cmr\/m\/n\/10 ([a-zA-Z.,;:'!?()~\-])$/) {
    $cur .= $1;
  } elsif (defined $cur && $l =~ /^\.+\\discretionary/) {
    # hyphen follows on next line as '..-'; mark
    $cur .= "\x01";
  } elsif (defined $cur && $l =~ /^\.+\.\\OT1\/cmr\/m\/n\/10 -$/) {
    $cur =~ s/\x01$//;
    $cur .= "-";
  } elsif (defined $cur && $l =~ /^\.+\\glue \d/) {
    $cur .= " ";
  } elsif ($l =~ /^Completed box/) { last if @out > 0; }
}
push @out, $cur if defined $cur;
for my $i (0..$#out) { printf "%2d: %s\n", $i+1, $out[$i]; }
EOF

